+++ b/internal/version/version.go
@@ -0,0 +1,15 @@
+package version
+
+import "strings"
+
+// Major extracts the major version, ignoring an optional epoch prefix.
+func Major(value string) string {
+	value = strings.TrimSpace(value)
+	if epoch := strings.IndexByte(value, ':'); epoch >= 0 {
+		value = value[epoch+1:]
+	}
+	if dot := strings.IndexByte(value, '.'); dot >= 0 {
+		return value[:dot]
+	}
+	return value
+}
